    // of the true center (validating that direction), but photo-based distance measurement
    // through a tiny ~14px reference ring was too noisy to trust for magnitude, so going with
    // the precise asset-derived figure instead: pivot = canvas(207,246), i.e.
    // object_x = 207-4, object_y = 246-78.
    lv_obj_set_x(face_red_magic_410_seconds_hand, 203);
