void update_time_red_magic_410(int second, int minute, int hour, bool mode, bool am, int day, int month, int year, int weekday)
{
#ifdef ENABLE_FACE_RED_MAGIC_410
    if (!face_red_magic_410)
    {
        return;
    }
	lv_img_set_src(face_red_magic_410_30_134849, face_red_magic_410_dial_img_30_134849_group[(month / 1) % 10]);
	lv_img_set_src(face_red_magic_410_31_134849, face_red_magic_410_dial_img_30_134849_group[(month / 10) % 10]);
	lv_img_set_src(face_red_magic_410_32_134849, face_red_magic_410_dial_img_30_134849_group[(day / 1) % 10]);
	lv_img_set_src(face_red_magic_410_33_134849, face_red_magic_410_dial_img_30_134849_group[(day / 10) % 10]);
	lv_img_set_src(face_red_magic_410_48_151287, face_red_magic_410_dial_img_48_151287_group[(hour / 1) % 10]);
	lv_img_set_src(face_red_magic_410_49_151287, face_red_magic_410_dial_img_48_151287_group[(hour / 10) % 10]);
	lv_img_set_src(face_red_magic_410_50_151287, face_red_magic_410_dial_img_48_151287_group[(minute / 1) % 10]);
	lv_img_set_src(face_red_magic_410_51_151287, face_red_magic_410_dial_img_48_151287_group[(minute / 10) % 10]);
	lv_image_set_rotation(face_red_magic_410_seconds_hand, second * 60);

#endif
}

void update_weather_red_magic_410(int temp, int icon)
{
#ifdef ENABLE_FACE_RED_MAGIC_410
    if (!face_red_magic_410)
    {
        return;
    }
	lv_img_set_src(face_red_magic_410_21_133464, face_red_magic_410_dial_img_weather[icon % 8]);

	// watch.getWeatherAt(0).temp is already Celsius, unconverted - confirmed against the
	// working 1167 face's update_weather_1167(), which uses raw temp directly.
	// Digit positions: items.txt has these 3 objects at x=70/60/50 - cross-checked against
	// this same file's working update_activity_red_magic_410() kcal digits (x=238/228/218/208
	// mapped to ones/tens/hundreds/thousands), higher x = lower place value. So x=70 (highest)
	// is ones, x=50 (lowest) is hundreds.
	int mag = temp < 0 ? -temp : temp;
	lv_img_set_src(face_red_magic_410_10_138312, face_red_magic_410_dial_img_10_138312_group[(mag / 1) % 10]);
	lv_img_set_src(face_red_magic_410_11_138312, face_red_magic_410_dial_img_10_138312_group[(mag / 10) % 10]);
	lv_img_set_src(face_red_magic_410_12_138312, face_red_magic_410_dial_img_10_138312_group[(mag / 100) % 10]);
	if (mag < 100)
	{
		// Belt-and-suspenders hide: HIDDEN flag alone left a speckled artifact on-device
		// (root cause not fully confirmed without a photo - possibly a stale/partial
		// invalidation on this particular object) so also physically move it off-canvas.
		// Digit content is always still set above regardless, ready to reappear at x=57
		// on the rare/impossible-for-Celsius chance this position is ever needed.
		lv_obj_add_flag(face_red_magic_410_12_138312, LV_OBJ_FLAG_HIDDEN);
		lv_obj_set_x(face_red_magic_410_12_138312, -100);
	} else {
		lv_obj_clear_flag(face_red_magic_410_12_138312, LV_OBJ_FLAG_HIDDEN);
		lv_obj_set_x(face_red_magic_410_12_138312, 57);
	}
	// face_red_magic_410_15_0 is a genuine minus-sign glyph (items.txt rows 8/9/15, type
	// 0xFA "Weather no+label" - fully supported by bin2lvgl, not one of the skipped Analog
	// elements) sitting directly under the hundreds-digit slot at the same x - it was always
	// being drawn, just permanently covered by that digit until the fix above started hiding
	// it, which is what exposed it as a stray dash on-device. Same belt-and-suspenders
	// treatment: shown only for genuinely negative temps, moved off-canvas otherwise.
	if (temp < 0)
	{
		lv_obj_clear_flag(face_red_magic_410_15_0, LV_OBJ_FLAG_HIDDEN);
		lv_obj_set_x(face_red_magic_410_15_0, 57);
	} else {
		lv_obj_add_flag(face_red_magic_410_15_0, LV_OBJ_FLAG_HIDDEN);
		lv_obj_set_x(face_red_magic_410_15_0, -100);
	}
	// face_red_magic_410_13_133026 = "°C" glyph, face_red_magic_410_14_136230 = "°F" glyph
	// (confirmed by decoding both assets directly - bin2lvgl gave no label metadata).
	lv_obj_clear_flag(face_red_magic_410_13_133026, LV_OBJ_FLAG_HIDDEN);
	lv_obj_add_flag(face_red_magic_410_14_136230, LV_OBJ_FLAG_HIDDEN);

#endif
}

